import{_ as s,o as e,c as t,a2 as p}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"楚茨","description":"","frontmatter":{"title":"楚茨","date":"2026-11-08T00:00:00.000Z","seq":49,"categories":["美文","诗经"],"collection":"《诗经 · 小雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·小雅/楚茨.md","filePath":"blogs/诗经·小雅/楚茨.md"}'),o={name:"blogs/诗经·小雅/楚茨.md"};function c(l,a,n,r,m,_){return e(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="楚茨" tabindex="-1">楚茨 <a class="header-anchor" href="#楚茨" aria-label="Permalink to &quot;楚茨&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　小雅 · 谷风之什</p><div class="poem"><p class="poem-stanza">楚楚者茨，言抽其棘，自昔何为？我蓺黍稷。我黍与与，我稷翼翼。</p><p class="poem-stanza">我仓既盈，我庾维亿。以为酒食，以享以祀，以妥以侑，以介景福。</p><p class="poem-stanza">济济跄跄，絜尔牛羊，以往烝尝。或剥或亨，或四或将。祝祭于祊，</p><p class="poem-stanza">祀事孔明。先祖是皇，神保是飨。孝孙有庆，报以介福，万寿无疆！</p><p class="poem-stanza">执爨踖踖，为俎孔硕，或燔或炙。君妇莫莫，为豆孔庶。为宾为客，</p><p class="poem-stanza">献酬交错。礼仪卒度，笑语卒获。神保是格，报以介福，万寿攸酢！</p><p class="poem-stanza">我孔戁矣，式礼莫愆。工祝致告，徂赉孝孙。苾芬孝祀，神嗜饮食。</p><p class="poem-stanza">卜尔百福，如几如式。既齐既稷，既匡既敕。永锡尔极，时万时亿！</p><p class="poem-stanza">礼仪既备，钟鼓既戒，孝孙徂位，工祝致告，神具醉止，皇尸载起。</p><p class="poem-stanza">鼓钟送尸，神保聿归。诸宰君妇，废彻不迟。诸父兄弟，备言燕私。</p><p class="poem-stanza">乐具入奏，以绥后禄。尔肴既将，莫怨具庆。既醉既饱，小大稽首。</p><p class="poem-stanza">神嗜饮食，使君寿考。孔惠孔时，维其尽之。子子孙孙，勿替引之！</p></div>',3)])])}const z=s(o,[["render",c]]);export{d as __pageData,z as default};
